import * as THREE from 'three';
export const spells=[['fire','Fireball','#ed7437'],['frost','Frost lance','#7ad6e8'],['lightning','Chain lightning','#a9a4fc'],['heal','Healing circle','#88c49e'],['arcane','Arcane burst','#aa87ea'],['meteor','Meteor','#e7a557'],['poison','Poison cloud','#a1b764'],['ward','Protective ward','#71bebc']];
export class Effects{
 constructor(scene){this.scene=scene;this.active=[];this.max=1400;this.positions=new Float32Array(this.max*3);this.colors=new Float32Array(this.max*3);this.velocities=new Float32Array(this.max*3);this.life=new Float32Array(this.max);this.total=new Float32Array(this.max);this.cursor=0;
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(this.positions,3));g.setAttribute('color',new THREE.BufferAttribute(this.colors,3));this.points=new THREE.Points(g,new THREE.PointsMaterial({size:.065,vertexColors:true,transparent:true,opacity:.82,depthWrite:false,blending:THREE.AdditiveBlending}));this.points.frustumCulled=false;scene.add(this.points);this.points.visible=false;this.tmp=new THREE.Vector3();
 }
 emit(pos,color,count=50,power=1){const c=new THREE.Color(color);for(let j=0;j<count;j++){const i=(this.cursor++)%this.max,k=i*3;this.positions[k]=pos.x;this.positions[k+1]=pos.y;this.positions[k+2]=pos.z;const a=j*2.39996,b=(j%17)/16*2-1,r=Math.sqrt(1-b*b)*power;this.velocities[k]=Math.cos(a)*r;this.velocities[k+1]=Math.sin(a)*r;this.velocities[k+2]=b*power+.4;this.colors[k]=c.r;this.colors[k+1]=c.g;this.colors[k+2]=c.b;this.life[i]=this.total[i]=.6+(j%13)*.07;}this.points.visible=true;}
 add(object,duration,update){this.scene.add(object);this.active.push({object,time:0,duration,update});}
 cast(type,origin){const color=spells.find(s=>s[0]===type)?.[2]||'#aa87ea';const source=origin.clone(),target=new THREE.Vector3(4.8,-1.6,2.4);this.emit(source,color,60,1.4);
  if(['heal','ward'].includes(type)){const root=new THREE.Group();root.position.set(0,0,.12);for(let k=0;k<3;k++){const geom=new THREE.TorusGeometry(1.1+k*.34,.016,5,64);const mat=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.75,depthWrite:false});const ring=new THREE.Mesh(geom,mat);ring.position.z=k*.08;root.add(ring);}if(type==='ward'){const sh=new THREE.Mesh(new THREE.IcosahedronGeometry(3.9,2),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.085,wireframe:true,depthWrite:false}));sh.position.z=3.7;root.add(sh);}this.add(root,2.6,(o,t)=>{o.rotation.z=t*.5;for(const ch of o.children)ch.material.opacity=(type==='ward'&&ch.geometry.type==='IcosahedronGeometry'?.1:.7)*Math.sin(t/2.6*Math.PI);});for(let i=0;i<100;i++){const a=i*2.4;this.tmp.set(Math.cos(a)*1.7,Math.sin(a)*1.2,1+(i%20)*.28);this.emit(this.tmp,color,1,.35);}return;}
  if(type==='lightning'){const root=new THREE.Group();const positions=[];for(let i=0;i<16;i++){const t=i/15;positions.push(source.x+(target.x-source.x)*t+(i>0&&i<15?Math.sin(i*27)*.25:0),source.y+(target.y-source.y)*t,source.z+(target.z-source.z)*t+Math.sin(i*15)*.22);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));root.add(new THREE.Line(g,new THREE.LineBasicMaterial({color,transparent:true,opacity:1,depthWrite:false})));this.add(root,.45,(o,t)=>{o.visible=Math.floor(t*35)%3!==0;});this.emit(target,color,140,2);return;}
  const root=new THREE.Group(),radius=type==='meteor'?.38:type==='poison'?.23:.18;const core=new THREE.Mesh(new THREE.IcosahedronGeometry(radius,1),new THREE.MeshBasicMaterial({color}));const halo=new THREE.Mesh(new THREE.IcosahedronGeometry(radius*2.1,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.2,depthWrite:false}));root.add(core,halo);if(type==='meteor')source.set(3.5,-1.5,10);root.position.copy(source);
  this.add(root,1.2,(o,time)=>{const t=Math.min(1,time/.85);o.position.lerpVectors(source,target,t);o.position.z+=Math.sin(Math.PI*t)*(type==='frost'?.1:.65);o.rotation.z+=.08;halo.scale.setScalar(1+Math.sin(time*30)*.15);if(t<1)this.emit(o.position,color,4,.35);else if(!o.userData.hit){o.userData.hit=true;this.emit(target,color,type==='meteor'?280:140,type==='poison'?.5:2.4);o.visible=false;}});
 }
 update(dt){for(let a=this.active.length-1;a>=0;a--){const e=this.active[a];e.time+=dt;e.update(e.object,e.time);if(e.time>=e.duration){e.object.removeFromParent();e.object.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});this.active.splice(a,1);}}
  let alive=0;for(let i=0;i<this.max;i++){const k=i*3;if(this.life[i]>0){this.life[i]-=dt;alive++;for(let j=0;j<3;j++)this.positions[k+j]+=this.velocities[k+j]*dt;this.velocities[k+2]-=dt*.45;const fade=Math.max(0,this.life[i]/this.total[i]);if(fade<.15){this.colors[k]*=.9;this.colors[k+1]*=.9;this.colors[k+2]*=.9;}}else{this.positions[k+2]=-100;}}
  if(alive){this.points.geometry.attributes.position.needsUpdate=true;this.points.geometry.attributes.color.needsUpdate=true;}this.points.visible=alive>0;
 }
 clear(){for(const e of this.active){e.object.removeFromParent();e.object.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}this.active=[];this.life.fill(0);this.points.visible=false;}
}
